$rows=$pdo->query('SELECT * FROM kak_documents ORDER BY id DESC')->fetchAll();$yr=date('Y');$ls=$pdo->prepare("SELECT MAX(CAST(SUBSTRING_INDEX(kak_no,'-',-1) AS UNSIGNED)) FROM kak_documents WHERE kak_no LIKE ?");$ls->execute(['KAK-'.$yr.'-%']);$next='KAK-'.$yr.'-'.str_pad((string)((int)$ls->fetchColumn()+1),4,'0',STR_PAD_LEFT);
?>
