<script>
const L=<?=json_encode($labels,JSON_UNESCAPED_UNICODE)?>,M=<?=json_encode($mat)?>,S=<?=json_encode($svc)?>,C=<?=json_encode($con)?>;
function renderScope(){
 const checked=document.querySelector('input[name="procurement_type"]:checked');
 const section=document.getElementById('scopeSection'), empty=document.getElementById('scopeEmpty'), fields=document.getElementById('scopeFields'), heading=document.getElementById('scopeHeading');
 document.querySelectorAll('.proc-choice').forEach(x=>x.classList.remove('selected'));
 if(!checked){section.style.display='none';empty.style.display='block';fields.innerHTML='';return;}
 checked.closest('.proc-choice').classList.add('selected');
 const t=checked.value, a=t==='Material / Barang'?M:t==='Jasa / Services'?S:C;
 const prefix=t==='Material / Barang'?'a. Material / Barang':t==='Jasa / Services'?'b. Jasa / Services':'c. Konsultan';
 heading.textContent='8. Ruang Lingkup Pekerjaan — '+prefix;
 fields.innerHTML=a.map(k=>`<div class="col-md-6"><label>${L[k]}</label><textarea class="form-control" rows="3" name="${k}"></textarea></div>`).join('');
 section.style.display='block';empty.style.display='none';
}
renderScope();
</script>
